insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-162', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'A Daniell cell with $E^\circ = 1.10\ \mathrm{V}$ has $[\mathrm{Zn^{2+}}] = 0.10\ \mathrm{M}$ and $[\mathrm{Cu^{2+}}] = 1.0\ \mathrm{M}$. $E$ at 298 K is nearest', '["$1.13\\ \\mathrm{V}$","$1.07\\ \\mathrm{V}$","$0.10\\ \\mathrm{V}$","$1.16\\ \\mathrm{V}$"]'::jsonb, 0, '$E = 1.10 - (0.059/2)\log(0.10/1.0) = 1.10 + 0.0295 = 1.13\ \mathrm{V}$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'nernst') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
