insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-183', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'A 2.0 A current flows for 965 s through acidified water. The STP volume of H$_2$ evolved is nearest', '["$0.224\\ \\mathrm{L}$","$22.4\\ \\mathrm{L}$","$0.112\\ \\mathrm{L}$","$2.24\\ \\mathrm{L}$"]'::jsonb, 0, '$Q = 1930\ \mathrm{C} = 0.020\ \mathrm{mol\ e^-}$; $2\,e^- \to 1\ \mathrm{H_2}$, so $0.010\ \mathrm{mol} = 0.224\ \mathrm{L}$ at STP.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'electrolysis-faraday') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
