insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-186', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'If 0.635 g of copper is plated from CuSO$_4$ in 1930 s, the steady current used was', '["$1.0\\ \\mathrm{A}$","$0.50\\ \\mathrm{A}$","$2.0\\ \\mathrm{A}$","$0.10\\ \\mathrm{A}$"]'::jsonb, 0, '$Q = (0.635 \times 2 \times 96500)/63.5 = 1930\ \mathrm{C}$; $I = Q/t = 1930/1930 = 1.0\ \mathrm{A}$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'electrolysis-faraday') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
